-- InternMate / Oracle ATP DDL. Run as ADMIN; creates objects only in INTERNMATE.
-- No CREATE USER, CREATE DATABASE, GRANT, or data-load statements are included.
-- Identity is BY DEFAULT so a later migration may retain SQLite IDs.

CREATE TABLE INTERNMATE.DJANGO_MIGRATIONS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, APP VARCHAR2(255 CHAR) NOT NULL, NAME VARCHAR2(255 CHAR) NOT NULL, APPLIED TIMESTAMP(6) NOT NULL);
CREATE TABLE INTERNMATE.DJANGO_CONTENT_TYPE (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, APP_LABEL VARCHAR2(100 CHAR) NOT NULL, MODEL VARCHAR2(100 CHAR) NOT NULL, UNIQUE (APP_LABEL,MODEL));
CREATE TABLE INTERNMATE.AUTH_PERMISSION (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NAME VARCHAR2(255 CHAR) NOT NULL, CONTENT_TYPE_ID NUMBER(19) NOT NULL, CODENAME VARCHAR2(100 CHAR) NOT NULL, UNIQUE(CONTENT_TYPE_ID,CODENAME), FOREIGN KEY(CONTENT_TYPE_ID) REFERENCES INTERNMATE.DJANGO_CONTENT_TYPE(ID));
CREATE TABLE INTERNMATE.AUTH_GROUP (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NAME VARCHAR2(150 CHAR) NOT NULL, UNIQUE(NAME));
CREATE TABLE INTERNMATE.AUTH_USER (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, PASSWORD VARCHAR2(128 CHAR) NOT NULL, LAST_LOGIN TIMESTAMP(6), IS_SUPERUSER NUMBER(1) NOT NULL, USERNAME VARCHAR2(150 CHAR) NOT NULL, LAST_NAME VARCHAR2(150 CHAR) NOT NULL, EMAIL VARCHAR2(254 CHAR) NOT NULL, IS_STAFF NUMBER(1) NOT NULL, IS_ACTIVE NUMBER(1) NOT NULL, DATE_JOINED TIMESTAMP(6) NOT NULL, FIRST_NAME VARCHAR2(150 CHAR) NOT NULL, UNIQUE(USERNAME), CHECK(IS_SUPERUSER IN(0,1)), CHECK(IS_STAFF IN(0,1)), CHECK(IS_ACTIVE IN(0,1)));
CREATE TABLE INTERNMATE.AUTH_GROUP_PERMISSIONS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, GROUP_ID NUMBER(19) NOT NULL, PERMISSION_ID NUMBER(19) NOT NULL, UNIQUE(GROUP_ID,PERMISSION_ID), FOREIGN KEY(GROUP_ID) REFERENCES INTERNMATE.AUTH_GROUP(ID) ON DELETE CASCADE, FOREIGN KEY(PERMISSION_ID) REFERENCES INTERNMATE.AUTH_PERMISSION(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.AUTH_USER_GROUPS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, USER_ID NUMBER(19) NOT NULL, GROUP_ID NUMBER(19) NOT NULL, UNIQUE(USER_ID,GROUP_ID), FOREIGN KEY(USER_ID) REFERENCES INTERNMATE.AUTH_USER(ID) ON DELETE CASCADE, FOREIGN KEY(GROUP_ID) REFERENCES INTERNMATE.AUTH_GROUP(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.AUTH_USER_USER_PERMISSIONS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, USER_ID NUMBER(19) NOT NULL, PERMISSION_ID NUMBER(19) NOT NULL, UNIQUE(USER_ID,PERMISSION_ID), FOREIGN KEY(USER_ID) REFERENCES INTERNMATE.AUTH_USER(ID) ON DELETE CASCADE, FOREIGN KEY(PERMISSION_ID) REFERENCES INTERNMATE.AUTH_PERMISSION(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.ACCOUNTS_USERPROFILE (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ROLE VARCHAR2(20 CHAR) DEFAULT 'INTERN' NOT NULL, USER_ID NUMBER(19) NOT NULL, UNIQUE(USER_ID), CHECK(ROLE IN('ADMIN','MENTOR','MANAGER','HR','INTERN')), FOREIGN KEY(USER_ID) REFERENCES INTERNMATE.AUTH_USER(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_DEPARTMENT (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, NAME VARCHAR2(120 CHAR) NOT NULL, UNIQUE(NAME));
CREATE TABLE INTERNMATE.OPERATIONS_SKILLDOMAIN (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, NAME VARCHAR2(120 CHAR) NOT NULL, UNIQUE(NAME));
CREATE TABLE INTERNMATE.OPERATIONS_MASTERDATALIST (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, NAME VARCHAR2(80 CHAR) NOT NULL, DESCRIPTION VARCHAR2(255 CHAR) NOT NULL, UNIQUE(NAME));
CREATE TABLE INTERNMATE.OPERATIONS_MASTERDATAITEM (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, VALUE VARCHAR2(100 CHAR) NOT NULL, DISPLAY_ORDER NUMBER(10) DEFAULT 1 NOT NULL, IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL, LIST_REF_ID NUMBER(19) NOT NULL, UNIQUE(LIST_REF_ID,VALUE), CHECK(DISPLAY_ORDER>=0), CHECK(IS_ACTIVE IN(0,1)), FOREIGN KEY(LIST_REF_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATALIST(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_PROJECT (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, PROJECT_CODE VARCHAR2(40 CHAR) NOT NULL, PROJECT_NAME VARCHAR2(255 CHAR) NOT NULL, STATUS VARCHAR2(20 CHAR) DEFAULT 'ACTIVE' NOT NULL, DESCRIPTION CLOB NOT NULL, DEPARTMENT_ID NUMBER(19) NOT NULL, UNIQUE(PROJECT_CODE), CHECK(STATUS IN('ACTIVE','ON_HOLD','COMPLETED')), FOREIGN KEY(DEPARTMENT_ID) REFERENCES INTERNMATE.OPERATIONS_DEPARTMENT(ID));
CREATE TABLE INTERNMATE.OPERATIONS_INTERNPROFILE (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, INTERN_CODE VARCHAR2(40 CHAR) NOT NULL, INTERNSHIP_START_DATE DATE NOT NULL, INTERNSHIP_END_DATE DATE NOT NULL, STATUS VARCHAR2(20 CHAR) DEFAULT 'ACTIVE' NOT NULL, DEPARTMENT_ID NUMBER(19) NOT NULL, MANAGER_ID NUMBER(19) NOT NULL, MENTOR_ID NUMBER(19) NOT NULL, USER_ID NUMBER(19) NOT NULL, UNIQUE(INTERN_CODE), UNIQUE(USER_ID), CHECK(STATUS IN('ACTIVE','COMPLETED','ON_HOLD')), CHECK(INTERNSHIP_END_DATE>=INTERNSHIP_START_DATE), FOREIGN KEY(DEPARTMENT_ID) REFERENCES INTERNMATE.OPERATIONS_DEPARTMENT(ID), FOREIGN KEY(MANAGER_ID) REFERENCES INTERNMATE.AUTH_USER(ID), FOREIGN KEY(MENTOR_ID) REFERENCES INTERNMATE.AUTH_USER(ID), FOREIGN KEY(USER_ID) REFERENCES INTERNMATE.AUTH_USER(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_INTERNPROFILE_SKILLS (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, INTERNPROFILE_ID NUMBER(19) NOT NULL, SKILLDOMAIN_ID NUMBER(19) NOT NULL, UNIQUE(INTERNPROFILE_ID,SKILLDOMAIN_ID), FOREIGN KEY(INTERNPROFILE_ID) REFERENCES INTERNMATE.OPERATIONS_INTERNPROFILE(ID) ON DELETE CASCADE, FOREIGN KEY(SKILLDOMAIN_ID) REFERENCES INTERNMATE.OPERATIONS_SKILLDOMAIN(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_INTERNPROJECTASSIGNMENT (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, IS_PRIMARY NUMBER(1) DEFAULT 0 NOT NULL, ASSIGNED_FROM DATE NOT NULL, ASSIGNED_TO DATE, INTERN_PROFILE_ID NUMBER(19) NOT NULL, PROJECT_ID NUMBER(19) NOT NULL, UNIQUE(INTERN_PROFILE_ID,PROJECT_ID,ASSIGNED_FROM), CHECK(IS_PRIMARY IN(0,1)), CHECK(ASSIGNED_TO IS NULL OR ASSIGNED_TO>=ASSIGNED_FROM), FOREIGN KEY(INTERN_PROFILE_ID) REFERENCES INTERNMATE.OPERATIONS_INTERNPROFILE(ID) ON DELETE CASCADE, FOREIGN KEY(PROJECT_ID) REFERENCES INTERNMATE.OPERATIONS_PROJECT(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, LOG_DATE DATE NOT NULL, TASK_NAME VARCHAR2(255 CHAR) NOT NULL, TASK_DESCRIPTION CLOB NOT NULL, PLANNED_WORK CLOB NOT NULL, ACTUAL_WORK CLOB NOT NULL, COMPLETION_PERCENTAGE NUMBER(5) DEFAULT 0 NOT NULL, WORKFLOW_STATE VARCHAR2(20 CHAR) DEFAULT 'DRAFT' NOT NULL, BLOCKER_FLAG NUMBER(1) DEFAULT 0 NOT NULL, BLOCKER_DESCRIPTION CLOB NOT NULL, SUPPORT_NEEDED CLOB NOT NULL, TIME_SPENT_HOURS NUMBER(5,2) DEFAULT 0 NOT NULL, EXPECTED_COMPLETION_DATE DATE, DELIVERABLE_LINK VARCHAR2(200 CHAR) NOT NULL, REMARKS CLOB NOT NULL, ON_TIME_COMPLETION_FLAG NUMBER(1) DEFAULT 0 NOT NULL, CREATED_BY_ID NUMBER(19) NOT NULL, UPDATED_BY_ID NUMBER(19) NOT NULL, INTERN_PROFILE_ID NUMBER(19) NOT NULL, COMPLETION_STATUS_ID NUMBER(19), FINAL_OWNER_ID NUMBER(19) NOT NULL, PRIORITY_ID NUMBER(19) NOT NULL, TASK_TYPE_ID NUMBER(19) NOT NULL, PROJECT_ID NUMBER(19) NOT NULL, CHECK(COMPLETION_PERCENTAGE BETWEEN 0 AND 100), CHECK(WORKFLOW_STATE IN('DRAFT','SUBMITTED','REVIEWED','REOPENED','CLOSED')), CHECK(BLOCKER_FLAG IN(0,1)), CHECK(ON_TIME_COMPLETION_FLAG IN(0,1)), CHECK(EXPECTED_COMPLETION_DATE IS NULL OR EXPECTED_COMPLETION_DATE>=LOG_DATE), FOREIGN KEY(CREATED_BY_ID) REFERENCES INTERNMATE.AUTH_USER(ID), FOREIGN KEY(UPDATED_BY_ID) REFERENCES INTERNMATE.AUTH_USER(ID), FOREIGN KEY(INTERN_PROFILE_ID) REFERENCES INTERNMATE.OPERATIONS_INTERNPROFILE(ID), FOREIGN KEY(COMPLETION_STATUS_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(FINAL_OWNER_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(PRIORITY_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(TASK_TYPE_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(PROJECT_ID) REFERENCES INTERNMATE.OPERATIONS_PROJECT(ID));
CREATE TABLE INTERNMATE.OPERATIONS_TASKDEPENDENCY (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, DEPENDENCY_TEXT VARCHAR2(255 CHAR) NOT NULL, DEPENDENCY_STATUS VARCHAR2(20 CHAR) DEFAULT 'OPEN' NOT NULL, ENTRY_ID NUMBER(19) NOT NULL, CHECK(DEPENDENCY_STATUS IN('OPEN','RESOLVED')), FOREIGN KEY(ENTRY_ID) REFERENCES INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(ID) ON DELETE CASCADE);
CREATE TABLE INTERNMATE.OPERATIONS_AIUSAGERECORD (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, AI_CONTRIBUTION_PERCENTAGE NUMBER(5) DEFAULT 0 NOT NULL, PROMPT_SUMMARY CLOB NOT NULL, ACCURACY_HELPFULNESS_RATING NUMBER(5) DEFAULT 0 NOT NULL, ESTIMATED_TIME_SAVED_HOURS NUMBER(5,2) DEFAULT 0 NOT NULL, USED_AI_FLAG NUMBER(1) DEFAULT 0 NOT NULL, ENTRY_ID NUMBER(19) NOT NULL, AI_ASSISTANCE_TYPE_ID NUMBER(19) NOT NULL, AI_TOOL_ID NUMBER(19) NOT NULL, HUMAN_REVIEW_STATUS_ID NUMBER(19) NOT NULL, OUTPUT_USAGE_ID NUMBER(19) NOT NULL, UNIQUE(ENTRY_ID), CHECK(AI_CONTRIBUTION_PERCENTAGE BETWEEN 0 AND 100), CHECK(USED_AI_FLAG IN(0,1)), FOREIGN KEY(ENTRY_ID) REFERENCES INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(ID) ON DELETE CASCADE, FOREIGN KEY(AI_ASSISTANCE_TYPE_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(AI_TOOL_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(HUMAN_REVIEW_STATUS_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID), FOREIGN KEY(OUTPUT_USAGE_ID) REFERENCES INTERNMATE.OPERATIONS_MASTERDATAITEM(ID));
CREATE TABLE INTERNMATE.OPERATIONS_MENTORREVIEWCOMMENT (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, ACTION VARCHAR2(20 CHAR) NOT NULL, COMMENT_TEXT CLOB NOT NULL, ACTION_AT TIMESTAMP(6) NOT NULL, ENTRY_ID NUMBER(19) NOT NULL, REVIEWER_ID NUMBER(19) NOT NULL, CHECK(ACTION IN('DRAFT','SUBMITTED','REVIEWED','REOPENED','CLOSED')), FOREIGN KEY(ENTRY_ID) REFERENCES INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(ID) ON DELETE CASCADE, FOREIGN KEY(REVIEWER_ID) REFERENCES INTERNMATE.AUTH_USER(ID));
CREATE TABLE INTERNMATE.OPERATIONS_AUDITLOG (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, CREATED_AT TIMESTAMP(6) NOT NULL, UPDATED_AT TIMESTAMP(6) NOT NULL, ENTITY_TYPE VARCHAR2(80 CHAR) NOT NULL, ENTITY_ID NUMBER(19) NOT NULL, ACTION_TYPE VARCHAR2(30 CHAR) NOT NULL, OLD_VALUE_JSON CLOB NOT NULL, NEW_VALUE_JSON CLOB NOT NULL, ACTOR_ID NUMBER(19) NOT NULL, CHECK(ENTITY_ID>=0), CHECK(OLD_VALUE_JSON IS JSON), CHECK(NEW_VALUE_JSON IS JSON), FOREIGN KEY(ACTOR_ID) REFERENCES INTERNMATE.AUTH_USER(ID));
CREATE TABLE INTERNMATE.DJANGO_ADMIN_LOG (ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ACTION_TIME TIMESTAMP(6) NOT NULL, OBJECT_ID CLOB, OBJECT_REPR VARCHAR2(200 CHAR) NOT NULL, ACTION_FLAG NUMBER(5) NOT NULL, CHANGE_MESSAGE CLOB NOT NULL, CONTENT_TYPE_ID NUMBER(19), USER_ID NUMBER(19) NOT NULL, CHECK(ACTION_FLAG>=0), FOREIGN KEY(CONTENT_TYPE_ID) REFERENCES INTERNMATE.DJANGO_CONTENT_TYPE(ID), FOREIGN KEY(USER_ID) REFERENCES INTERNMATE.AUTH_USER(ID));
CREATE TABLE INTERNMATE.DJANGO_SESSION (SESSION_KEY VARCHAR2(40 CHAR) PRIMARY KEY, SESSION_DATA CLOB NOT NULL, EXPIRE_DATE TIMESTAMP(6) NOT NULL);

-- Explicit non-unique indexes; unique/primary-key constraints create their own indexes.
CREATE INDEX INTERNMATE.IX_AP_CT ON INTERNMATE.AUTH_PERMISSION(CONTENT_TYPE_ID);
CREATE INDEX INTERNMATE.IX_AGP_P ON INTERNMATE.AUTH_GROUP_PERMISSIONS(PERMISSION_ID);
CREATE INDEX INTERNMATE.IX_AUG_G ON INTERNMATE.AUTH_USER_GROUPS(GROUP_ID);
CREATE INDEX INTERNMATE.IX_AUUP_P ON INTERNMATE.AUTH_USER_USER_PERMISSIONS(PERMISSION_ID);
CREATE INDEX INTERNMATE.IX_DAL_CT ON INTERNMATE.DJANGO_ADMIN_LOG(CONTENT_TYPE_ID);
CREATE INDEX INTERNMATE.IX_DAL_U ON INTERNMATE.DJANGO_ADMIN_LOG(USER_ID);
CREATE INDEX INTERNMATE.IX_DS_EXPIRE ON INTERNMATE.DJANGO_SESSION(EXPIRE_DATE);
CREATE INDEX INTERNMATE.IX_OMDI_LIST ON INTERNMATE.OPERATIONS_MASTERDATAITEM(LIST_REF_ID);
CREATE INDEX INTERNMATE.IX_OP_DEPT ON INTERNMATE.OPERATIONS_PROJECT(DEPARTMENT_ID);
CREATE INDEX INTERNMATE.IX_OIP_DEPT ON INTERNMATE.OPERATIONS_INTERNPROFILE(DEPARTMENT_ID);
CREATE INDEX INTERNMATE.IX_OIP_MANAGER ON INTERNMATE.OPERATIONS_INTERNPROFILE(MANAGER_ID);
CREATE INDEX INTERNMATE.IX_OIP_MENTOR ON INTERNMATE.OPERATIONS_INTERNPROFILE(MENTOR_ID);
CREATE INDEX INTERNMATE.IX_OIPS_SKILL ON INTERNMATE.OPERATIONS_INTERNPROFILE_SKILLS(SKILLDOMAIN_ID);
CREATE INDEX INTERNMATE.IX_OIPA_PROJECT ON INTERNMATE.OPERATIONS_INTERNPROJECTASSIGNMENT(PROJECT_ID);
CREATE INDEX INTERNMATE.IX_DPE_CB ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(CREATED_BY_ID);
CREATE INDEX INTERNMATE.IX_DPE_UB ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(UPDATED_BY_ID);
CREATE INDEX INTERNMATE.IX_DPE_INTERN ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(INTERN_PROFILE_ID);
CREATE INDEX INTERNMATE.IX_DPE_CS ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(COMPLETION_STATUS_ID);
CREATE INDEX INTERNMATE.IX_DPE_FO ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(FINAL_OWNER_ID);
CREATE INDEX INTERNMATE.IX_DPE_PR ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(PRIORITY_ID);
CREATE INDEX INTERNMATE.IX_DPE_TT ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(TASK_TYPE_ID);
CREATE INDEX INTERNMATE.IX_DPE_PROJECT ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(PROJECT_ID);
CREATE INDEX INTERNMATE.IX_DPE_ORDER ON INTERNMATE.OPERATIONS_DAILYPROGRESSENTRY(LOG_DATE DESC,UPDATED_AT DESC);
CREATE INDEX INTERNMATE.IX_OTD_ENTRY ON INTERNMATE.OPERATIONS_TASKDEPENDENCY(ENTRY_ID);
CREATE INDEX INTERNMATE.IX_OAI_AT ON INTERNMATE.OPERATIONS_AIUSAGERECORD(AI_ASSISTANCE_TYPE_ID);
CREATE INDEX INTERNMATE.IX_OAI_TOOL ON INTERNMATE.OPERATIONS_AIUSAGERECORD(AI_TOOL_ID);
CREATE INDEX INTERNMATE.IX_OAI_HR ON INTERNMATE.OPERATIONS_AIUSAGERECORD(HUMAN_REVIEW_STATUS_ID);
CREATE INDEX INTERNMATE.IX_OAI_OUT ON INTERNMATE.OPERATIONS_AIUSAGERECORD(OUTPUT_USAGE_ID);
CREATE INDEX INTERNMATE.IX_OMRC_ENTRY ON INTERNMATE.OPERATIONS_MENTORREVIEWCOMMENT(ENTRY_ID);
CREATE INDEX INTERNMATE.IX_OMRC_REVIEWER ON INTERNMATE.OPERATIONS_MENTORREVIEWCOMMENT(REVIEWER_ID);
CREATE INDEX INTERNMATE.IX_OAL_ACTOR ON INTERNMATE.OPERATIONS_AUDITLOG(ACTOR_ID);
CREATE INDEX INTERNMATE.IX_OAL_ORDER ON INTERNMATE.OPERATIONS_AUDITLOG(CREATED_AT DESC);
